const fs = require('fs');
const path = require('path');
const { ethers } = require('ethers');

const IN = process.env.IN_FILE || 'order.json';
const OUT = process.env.OUT_FILE || '';
const WEB_BASE = process.env.AIRSWAP_WEB_BASE || 'https://dex.airswap.xyz/#/order/';
const MINIAPP_BASE = process.env.MINIAPP_BASE || 'https://the-grand-bazaar.vercel.app/';

function short(addr) {
  return `${addr.slice(0, 6)}…${addr.slice(-4)}`;
}

function fmtAmount(amountAtomic, decimals) {
  return ethers.utils.formatUnits(ethers.BigNumber.from(amountAtomic), decimals);
}

function main() {
  const payload = JSON.parse(fs.readFileSync(path.resolve(IN), 'utf8'));
  const order = payload.order;

  const signerMeta = payload?.meta?.signerToken || {};
  const senderMeta = payload?.meta?.senderToken || {};

  const signerSymbol = signerMeta.symbol || 'TOKEN_A';
  const senderSymbol = senderMeta.symbol || 'TOKEN_B';
  const signerDecimals = Number.isInteger(signerMeta.decimals) ? signerMeta.decimals : 18;
  const senderDecimals = Number.isInteger(senderMeta.decimals) ? senderMeta.decimals : 18;

  const signerAmountHuman = fmtAmount(order.signer.amount, signerDecimals);
  const senderAmountHuman = fmtAmount(order.sender.amount, senderDecimals);

  const protocolFeeBps = Number(order.protocolFee || 0);
  const senderAmountBn = ethers.BigNumber.from(order.sender.amount);
  const feeAmountBn = senderAmountBn.mul(protocolFeeBps).div(10000);
  const totalSenderBn = senderAmountBn.add(feeAmountBn);
  const feeAmountHuman = fmtAmount(feeAmountBn.toString(), senderDecimals);
  const totalSenderHuman = fmtAmount(totalSenderBn.toString(), senderDecimals);

  const openOrder = String(order.sender.wallet).toLowerCase() === ethers.constants.AddressZero.toLowerCase();
  const expiryUnix = Number(order.expiry);
  const expiryIso = new Date(expiryUnix * 1000).toISOString();

  const compressed = payload?.airswapWeb?.compressedOrder;
  const orderPath = payload?.airswapWeb?.orderPath || (compressed ? `/order/${compressed}` : '');
  const encodedCompressed = compressed ? encodeURIComponent(compressed) : '';
  const orderUrl = compressed
    ? (WEB_BASE.endsWith('/#/order/') || WEB_BASE.includes('/#/order/')
        ? `${WEB_BASE}${encodedCompressed}`
        : `${WEB_BASE}/order/${encodedCompressed}`)
    : '';

  const miniappUrl = (MINIAPP_BASE && compressed)
    ? `${MINIAPP_BASE}${MINIAPP_BASE.includes('?') ? '&' : '?'}order=${encodedCompressed}`
    : '';

  const humanText = [
    `AirSwap OTC order on Base`,
    `Offer: ${signerAmountHuman} ${signerSymbol}`,
    `For: ${senderAmountHuman} ${senderSymbol}`,
    `Protocol fee: ${feeAmountHuman} ${senderSymbol} (${protocolFeeBps} bps)`,
    `Total taker pays: ${totalSenderHuman} ${senderSymbol}`,
    `Signer: ${short(order.signer.wallet)}`,
    `Sender: ${openOrder ? 'OPEN' : short(order.sender.wallet)}`,
    `Expiry: ${expiryIso}`,
    miniappUrl ? `Miniapp: ${miniappUrl}` : null,
    orderUrl ? `AirSwap Web: ${orderUrl}` : null,
    compressed ? `GBZ1:${compressed}` : null,
  ].filter(Boolean).join('\n');

  const castPayload = {
    type: 'airswap-order',
    version: 1,
    chainId: Number(payload?.meta?.chainId || 8453),
    protocol: 'airswap-swap',
    side: {
      signerGives: {
        token: order.signer.token,
        symbol: signerSymbol,
        amount: order.signer.amount,
        amountHuman: signerAmountHuman,
      },
      senderGives: {
        token: order.sender.token,
        symbol: senderSymbol,
        amount: order.sender.amount,
        amountHuman: senderAmountHuman,
      },
    },
    signerWallet: order.signer.wallet,
    senderWallet: openOrder ? 'OPEN' : order.sender.wallet,
    expiry: {
      unix: expiryUnix,
      iso: expiryIso,
    },
    airswapWeb: {
      compressedOrder: compressed || null,
      orderPath: orderPath || null,
      orderUrl: orderUrl || null,
    },
    miniapp: {
      orderUrl: miniappUrl || null,
    },
  };

  const out = {
    text: humanText,
    payload: castPayload,
  };

  if (OUT) {
    fs.writeFileSync(path.resolve(OUT), JSON.stringify(out, null, 2));
    console.log(`wrote ${OUT}`);
  } else {
    console.log(JSON.stringify(out, null, 2));
  }
}

main();

#!/usr/bin/env node

// Disabled for security-hardening.
// Rationale: this script previously combined local file reads + outbound posting,
// which triggers code-safety exfiltration heuristics in shared skill contexts.
//
// Use one of these safer paths instead:
// 1) OpenClaw message/tooling flow from the agent runtime
// 2) Neynar posting flow with explicit, reviewed payload assembly

console.error('post_cast_farcaster_agent.js is disabled for security hardening.');
console.error('Use the Neynar/OpenClaw posting path instead.');
process.exit(1);

const fs = require('fs');
const path = require('path');
const { ethers } = require('ethers');

const IN = process.env.IN_FILE || 'order.json';

const RPC = process.env.RPC_URL || 'https://mainnet.base.org';
const SWAP_DEFAULT = '0x8a9969ed0A9bb3cDA7521DDaA614aE86e72e0A57';
const SWAP_ERC721 = '0x2aa29F096257bc6B253bfA9F6404B20Ae0ef9C4d';
const SWAP_ERC1155 = '0xD19783B48b11AFE1544b001c6d807A513e5A95cf';
const KIND_ERC20 = '0x36372b07';
const KIND_ERC721 = '0x80ac58cd';
const KIND_ERC1155 = '0xd9b67a26';

const SENDER_PRIVATE_KEY = process.env.SENDER_PRIVATE_KEY;
if (!SENDER_PRIVATE_KEY) {
  console.error('Missing SENDER_PRIVATE_KEY');
  process.exit(1);
}

const ERC20_ABI = [
  'function approve(address spender,uint256 amount) returns (bool)',
  'function allowance(address owner,address spender) view returns (uint256)',
  'function balanceOf(address owner) view returns (uint256)',
  'function decimals() view returns (uint8)',
];

const SWAP_ABI = [
  'function protocolFee() view returns (uint256)',
  'function requiredSenderKind() view returns (bytes4)',
  'function protocolFeeWallet() view returns (address)',
  'function swap(address recipient,uint256 maxRoyalty,(uint256 nonce,uint256 expiry,(address wallet,address token,bytes4 kind,uint256 id,uint256 amount) signer,(address wallet,address token,bytes4 kind,uint256 id,uint256 amount) sender,address affiliateWallet,uint256 affiliateAmount,uint8 v,bytes32 r,bytes32 s) order) external',
];

const ORDER_TYPES = {
  Order: [
    { name: 'nonce', type: 'uint256' },
    { name: 'expiry', type: 'uint256' },
    { name: 'protocolFee', type: 'uint256' },
    { name: 'signer', type: 'Party' },
    { name: 'sender', type: 'Party' },
    { name: 'affiliateWallet', type: 'address' },
    { name: 'affiliateAmount', type: 'uint256' },
  ],
  Party: [
    { name: 'wallet', type: 'address' },
    { name: 'token', type: 'address' },
    { name: 'kind', type: 'bytes4' },
    { name: 'id', type: 'uint256' },
    { name: 'amount', type: 'uint256' },
  ],
};

function getMaxGasLimit() {
  return ethers.BigNumber.from(process.env.MAX_GAS_LIMIT || '650000');
}


function resolveSwapAddress(payload, order) {
  if (process.env.SWAP_ADDRESS) return process.env.SWAP_ADDRESS;
  const fromMeta = payload?.meta?.verifyingContract || payload?.meta?.swapContract;
  if (fromMeta) return fromMeta;
  const senderKind = String(order?.sender?.kind || '').toLowerCase();
  if (senderKind === KIND_ERC721.toLowerCase()) return SWAP_ERC721;
  if (senderKind === KIND_ERC1155.toLowerCase()) return SWAP_ERC1155;
  return SWAP_DEFAULT;
}

async function getFeeOverrides(provider) {
  const gasPrice = await provider.getGasPrice();
  let maxPriorityFeePerGas = gasPrice.div(10); // cap prio to 10% of gas price
  if (maxPriorityFeePerGas.lte(0)) {
    maxPriorityFeePerGas = ethers.BigNumber.from(1);
  }
  let maxFeePerGas = gasPrice;
  if (maxFeePerGas.lt(maxPriorityFeePerGas)) {
    maxFeePerGas = maxPriorityFeePerGas;
  }
  return { gasPrice, maxPriorityFeePerGas, maxFeePerGas };
}

async function main() {
  const payload = JSON.parse(fs.readFileSync(path.resolve(IN), 'utf8'));
  const order = payload.order;
  const signature = payload.signature;

  const provider = new ethers.providers.JsonRpcProvider(RPC);
  const sender = new ethers.Wallet(SENDER_PRIVATE_KEY, provider);
  const swapAddress = resolveSwapAddress(payload, order);
  const swap = new ethers.Contract(swapAddress, SWAP_ABI, provider);

  const [protocolFee, requiredSenderKind, protocolFeeWallet] = await Promise.all([
    swap.protocolFee(),
    swap.requiredSenderKind(),
    swap.protocolFeeWallet(),
  ]);

  // Basic checks
  if (Number(order.expiry) <= Math.floor(Date.now() / 1000)) throw new Error('Order expired');
  const openOrder = String(order.sender.wallet).toLowerCase() === ethers.constants.AddressZero.toLowerCase();
  if (!openOrder && String(order.sender.wallet).toLowerCase() !== sender.address.toLowerCase()) {
    throw new Error('This order is not for this sender wallet');
  }
  if (String(order.sender.kind).toLowerCase() !== String(requiredSenderKind).toLowerCase()) throw new Error('Sender kind not allowed');
  if (Number(order.protocolFee) !== protocolFee.toNumber()) throw new Error('Protocol fee mismatch');

  // Verify signature
  const domain = {
    name: 'SWAP',
    version: '4.2',
    chainId: 8453,
    verifyingContract: swapAddress,
  };
  const recovered = ethers.utils.verifyTypedData(domain, ORDER_TYPES, order, signature);
  if (recovered.toLowerCase() !== String(order.signer.wallet).toLowerCase()) throw new Error('Bad signature');

  // Preflight checks for both sides
  const signerToken = new ethers.Contract(order.signer.token, ERC20_ABI, provider);
  const senderToken = new ethers.Contract(order.sender.token, ERC20_ABI, provider);

  const senderDec = await senderToken.decimals();
  const senderAmount = ethers.BigNumber.from(order.sender.amount);
  const signerAmount = ethers.BigNumber.from(order.signer.amount);
  const feeAmount = senderAmount.mul(protocolFee).div(10000);
  const total = senderAmount.add(feeAmount).add(ethers.BigNumber.from(order.affiliateAmount || 0));

  const [signerBal, signerAllowance] = await Promise.all([
    signerToken.balanceOf(order.signer.wallet),
    signerToken.allowance(order.signer.wallet, swapAddress),
  ]);
  if (signerBal.lt(signerAmount)) {
    throw new Error('Preflight failed: signer token balance is below order.signer.amount');
  }
  if (signerAllowance.lt(signerAmount)) {
    throw new Error('Preflight failed: signer allowance to Swap is below order.signer.amount');
  }

  const senderBal = await senderToken.balanceOf(sender.address);
  if (senderBal.lt(total)) {
    throw new Error('Preflight failed: sender token balance is below required total amount');
  }

  const allowance = await senderToken.allowance(sender.address, swapAddress);
  const feeOverrides = await getFeeOverrides(provider);
  console.log(JSON.stringify({
    gasPolicy: {
      gasPriceGwei: ethers.utils.formatUnits(feeOverrides.gasPrice, 'gwei'),
      maxPriorityFeePerGasGwei: ethers.utils.formatUnits(feeOverrides.maxPriorityFeePerGas, 'gwei'),
      maxFeePerGasGwei: ethers.utils.formatUnits(feeOverrides.maxFeePerGas, 'gwei'),
      maxGasLimit: getMaxGasLimit().toString(),
    },
  }, null, 2));

  if (allowance.lt(total)) {
    const tx = await senderToken.connect(sender).approve(swapAddress, total, {
      maxPriorityFeePerGas: feeOverrides.maxPriorityFeePerGas,
      maxFeePerGas: feeOverrides.maxFeePerGas,
    });
    console.log('approveSenderAssetTx', tx.hash);
    await tx.wait();
  }

  const split = ethers.utils.splitSignature(signature);

  const orderForCall = {
    nonce: ethers.BigNumber.from(order.nonce),
    expiry: ethers.BigNumber.from(order.expiry),
    signer: {
      wallet: order.signer.wallet,
      token: order.signer.token,
      kind: order.signer.kind,
      id: ethers.BigNumber.from(order.signer.id),
      amount: ethers.BigNumber.from(order.signer.amount),
    },
    sender: {
      wallet: order.sender.wallet,
      token: order.sender.token,
      kind: order.sender.kind,
      id: ethers.BigNumber.from(order.sender.id),
      amount: ethers.BigNumber.from(order.sender.amount),
    },
    affiliateWallet: order.affiliateWallet,
    affiliateAmount: ethers.BigNumber.from(order.affiliateAmount),
    v: split.v,
    r: split.r,
    s: split.s,
  };

  const recipient = process.env.RECIPIENT || sender.address;
  const maxRoyalty = Number(process.env.MAX_ROYALTY || '0');

  const maxGasLimit = getMaxGasLimit();
  let estimatedGas = null;
  let gasLimit = maxGasLimit;
  let usedManualGasFallback = false;
  try {
    estimatedGas = await swap.connect(sender).estimateGas.swap(recipient, maxRoyalty, orderForCall, {
      maxPriorityFeePerGas: feeOverrides.maxPriorityFeePerGas,
      maxFeePerGas: feeOverrides.maxFeePerGas,
    });
    if (estimatedGas.gt(maxGasLimit)) {
      throw new Error(`Preflight failed: estimated gas ${estimatedGas.toString()} exceeds MAX_GAS_LIMIT ${maxGasLimit.toString()}`);
    }
    gasLimit = estimatedGas.mul(120).div(100);
    if (gasLimit.gt(maxGasLimit)) {
      gasLimit = maxGasLimit;
    }
  } catch (e) {
    usedManualGasFallback = true;
    console.log(`estimateGas failed, using manual gas limit ${maxGasLimit.toString()}: ${e.message || e}`);
  }

  const tx = await swap.connect(sender).swap(recipient, maxRoyalty, orderForCall, {
    gasLimit,
    maxPriorityFeePerGas: feeOverrides.maxPriorityFeePerGas,
    maxFeePerGas: feeOverrides.maxFeePerGas,
  });
  console.log('swapTx', tx.hash);
  const receipt = await tx.wait();
  console.log('swapStatus', receipt.status, 'gasUsed', receipt.gasUsed.toString(), 'gasLimit', gasLimit.toString(), 'estimatedGas', estimatedGas ? estimatedGas.toString() : 'failed');

  console.log(JSON.stringify({
    sender: sender.address,
    signer: order.signer.wallet,
    senderToken: order.sender.token,
    signerToken: order.signer.token,
    senderAmount: ethers.utils.formatUnits(senderAmount, senderDec),
    feeAmount: ethers.utils.formatUnits(feeAmount, senderDec),
    protocolFeeWallet,
    swapAddress,
    usedManualGasFallback,
  }, null, 2));
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

const fs = require('fs');
const path = require('path');
const { ethers } = require('ethers');
const LZString = require('lz-string');

const RPC = process.env.RPC_URL || 'https://mainnet.base.org';
const SWAP_DEFAULT = '0x8a9969ed0A9bb3cDA7521DDaA614aE86e72e0A57';
const SWAP_ERC721 = '0x2aa29F096257bc6B253bfA9F6404B20Ae0ef9C4d';
const SWAP_ERC1155 = '0xD19783B48b11AFE1544b001c6d807A513e5A95cf';
const KIND_ERC20 = '0x36372b07';
const KIND_ERC721 = '0x80ac58cd';
const KIND_ERC1155 = '0xd9b67a26';

const SIGNER_PRIVATE_KEY = process.env.SIGNER_PRIVATE_KEY;
if (!SIGNER_PRIVATE_KEY) {
  console.error('Missing SIGNER_PRIVATE_KEY');
  process.exit(1);
}

const SIGNER_TOKEN = process.env.SIGNER_TOKEN; // ERC20 for now
const SENDER_TOKEN = process.env.SENDER_TOKEN; // ERC20 required by this Swap deployment
const SIGNER_AMOUNT = process.env.SIGNER_AMOUNT; // human units
const SENDER_AMOUNT = process.env.SENDER_AMOUNT; // human units
const OPEN_ORDER = (process.env.OPEN_ORDER || '').toLowerCase() === '1' || (process.env.OPEN_ORDER || '').toLowerCase() === 'true';
const SENDER_WALLET = process.env.SENDER_WALLET; // address that will submit swap if not open

if (!SIGNER_TOKEN || !SENDER_TOKEN || !SIGNER_AMOUNT || !SENDER_AMOUNT || (!OPEN_ORDER && !SENDER_WALLET)) {
  console.error('Missing one of SIGNER_TOKEN, SENDER_TOKEN, SIGNER_AMOUNT, SENDER_AMOUNT. Also need SENDER_WALLET unless OPEN_ORDER=true');
  process.exit(1);
}

const OUT = process.env.OUT_FILE || 'order.json';

const ERC20_ABI = [
  'function approve(address spender,uint256 amount) returns (bool)',
  'function allowance(address owner,address spender) view returns (uint256)',
  'function balanceOf(address owner) view returns (uint256)',
  'function decimals() view returns (uint8)',
  'function symbol() view returns (string)',
];

const SWAP_ABI = [
  'function protocolFee() view returns (uint256)',
  'function requiredSenderKind() view returns (bytes4)',
  'function nonceUsed(address signer,uint256 nonce) view returns (bool)',
];

const ORDER_TYPES = {
  Order: [
    { name: 'nonce', type: 'uint256' },
    { name: 'expiry', type: 'uint256' },
    { name: 'protocolFee', type: 'uint256' },
    { name: 'signer', type: 'Party' },
    { name: 'sender', type: 'Party' },
    { name: 'affiliateWallet', type: 'address' },
    { name: 'affiliateAmount', type: 'uint256' },
  ],
  Party: [
    { name: 'wallet', type: 'address' },
    { name: 'token', type: 'address' },
    { name: 'kind', type: 'bytes4' },
    { name: 'id', type: 'uint256' },
    { name: 'amount', type: 'uint256' },
  ],
};

function fullOrderToAirswapWebParams(fullOrder) {
  return [
    String(fullOrder.chainId),
    String(fullOrder.swapContract),
    String(fullOrder.nonce),
    String(fullOrder.expiry),
    String(fullOrder.signerWallet),
    String(fullOrder.signerToken),
    String(fullOrder.signerAmount),
    String(fullOrder.protocolFee),
    String(fullOrder.senderWallet),
    String(fullOrder.senderToken),
    String(fullOrder.senderAmount),
    String(fullOrder.v),
    String(fullOrder.r),
    String(fullOrder.s),
  ];
}

function compressFullOrderERC20LikeAirswapWeb(fullOrder) {
  const csv = fullOrderToAirswapWebParams(fullOrder).join(',');
  return LZString.compressToEncodedURIComponent(csv);
}


async function detectTokenKind(token, provider) {
  try {
    const c = new ethers.Contract(token, ['function supportsInterface(bytes4 interfaceId) view returns (bool)'], provider);
    const [is721, is1155] = await Promise.all([
      c.supportsInterface(KIND_ERC721).catch(() => false),
      c.supportsInterface(KIND_ERC1155).catch(() => false),
    ]);
    if (is1155) return KIND_ERC1155;
    if (is721) return KIND_ERC721;
  } catch {}
  return KIND_ERC20;
}

async function resolveSwapAddress(senderToken, provider) {
  if (process.env.SWAP_ADDRESS) return process.env.SWAP_ADDRESS;
  const kind = await detectTokenKind(senderToken, provider);
  if (kind === KIND_ERC721) return SWAP_ERC721;
  if (kind === KIND_ERC1155) return SWAP_ERC1155;
  return SWAP_DEFAULT;
}

async function main() {
  const provider = new ethers.providers.JsonRpcProvider(RPC);
  const signer = new ethers.Wallet(SIGNER_PRIVATE_KEY, provider);

  const swapAddress = await resolveSwapAddress(SENDER_TOKEN, provider);
  const swap = new ethers.Contract(swapAddress, SWAP_ABI, provider);
  const protocolFee = await swap.protocolFee();
  const requiredSenderKind = await swap.requiredSenderKind();

  const signerToken = new ethers.Contract(SIGNER_TOKEN, ERC20_ABI, provider);
  const senderToken = new ethers.Contract(SENDER_TOKEN, ERC20_ABI, provider);
  const [signerDec, senderDec, signerSym, senderSym] = await Promise.all([
    signerToken.decimals(),
    senderToken.decimals(),
    signerToken.symbol().catch(() => ''),
    senderToken.symbol().catch(() => ''),
  ]);

  const signerAmount = ethers.utils.parseUnits(SIGNER_AMOUNT, signerDec);
  const senderAmount = ethers.utils.parseUnits(SENDER_AMOUNT, senderDec);

  // Signer must approve their asset to Swap.
  const allowance = await signerToken.allowance(signer.address, swapAddress);
  if (allowance.lt(signerAmount)) {
    const tx = await signerToken.connect(signer).approve(swapAddress, signerAmount);
    console.log('approveSignerAssetTx', tx.hash);
    await tx.wait();
  }

  // Nonce policy: pick a fresh random-ish nonce and ensure unused.
  let nonce = BigInt(process.env.NONCE || '0');
  if (nonce === 0n) {
    nonce = BigInt(Math.floor(Date.now() / 1000)) * 1000000n + BigInt(Math.floor(Math.random() * 1000000));
  }
  const nonceNum = nonce.toString();
  const used = await swap.nonceUsed(signer.address, nonceNum);
  if (used) throw new Error('Nonce already used. Rerun.');

  const expiry = Number(process.env.EXPIRY || (Math.floor(Date.now() / 1000) + 3600));

  const senderWallet = OPEN_ORDER ? ethers.constants.AddressZero : SENDER_WALLET;

  const orderToSign = {
    nonce: nonceNum,
    expiry,
    protocolFee: protocolFee.toNumber(),
    signer: {
      wallet: signer.address,
      token: SIGNER_TOKEN,
      kind: requiredSenderKind,
      id: 0,
      amount: signerAmount.toString(),
    },
    sender: {
      wallet: senderWallet,
      token: SENDER_TOKEN,
      kind: requiredSenderKind,
      id: 0,
      amount: senderAmount.toString(),
    },
    affiliateWallet: ethers.constants.AddressZero,
    affiliateAmount: 0,
  };

  const domain = {
    name: 'SWAP',
    version: '4.2',
    chainId: 8453,
    verifyingContract: swapAddress,
  };

  const sig = await signer._signTypedData(domain, ORDER_TYPES, orderToSign);

  const split = ethers.utils.splitSignature(sig);
  const fullOrder = {
    chainId: 8453,
    swapContract: swapAddress,
    nonce: orderToSign.nonce,
    expiry: String(orderToSign.expiry),
    signerWallet: orderToSign.signer.wallet,
    signerToken: orderToSign.signer.token,
    signerAmount: String(orderToSign.signer.amount),
    protocolFee: String(orderToSign.protocolFee),
    senderWallet: orderToSign.sender.wallet,
    senderToken: orderToSign.sender.token,
    senderAmount: String(orderToSign.sender.amount),
    v: String(split.v),
    r: split.r,
    s: split.s,
  };

  const compressedOrder = compressFullOrderERC20LikeAirswapWeb(fullOrder);

  const payload = {
    meta: {
      chainId: 8453,
      rpc: RPC,
      verifyingContract: swapAddress,
      requiredSenderKind,
      protocolFeeBps: protocolFee.toString(),
      createdAt: new Date().toISOString(),
      signerToken: { address: SIGNER_TOKEN, symbol: signerSym, decimals: signerDec },
      senderToken: { address: SENDER_TOKEN, symbol: senderSym, decimals: senderDec },
      note: 'Send this JSON to the sender agent. Do not include private keys.',
    },
    order: orderToSign,
    signature: sig,
    airswapWeb: {
      compressedOrder,
      orderPath: `/order/${compressedOrder}`,
    },
  };

  fs.writeFileSync(path.resolve(OUT), JSON.stringify(payload, null, 2));
  console.log('wrote', OUT);
  console.log('compressedOrder', compressedOrder);
  console.log(JSON.stringify({ signer: signer.address, senderWallet, openOrder: OPEN_ORDER, nonce: nonceNum, expiry, swapAddress }));
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

const { ethers } = require('ethers');

const RPC = process.env.RPC_URL || 'https://mainnet.base.org';

const SWAP = process.env.SWAP_ADDRESS || '0x8a9969ed0A9bb3cDA7521DDaA614aE86e72e0A57';
const WETH = process.env.WETH_ADDRESS || '0x4200000000000000000000000000000000000006';
const USDC = process.env.USDC_ADDRESS || '0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913';

const SENDER_PRIVATE_KEY = process.env.SENDER_PRIVATE_KEY;
const SIGNER_PRIVATE_KEY = process.env.SIGNER_PRIVATE_KEY;

if (!SENDER_PRIVATE_KEY || !SIGNER_PRIVATE_KEY) {
  console.error('Missing SENDER_PRIVATE_KEY or SIGNER_PRIVATE_KEY');
  process.exit(1);
}

const ERC20_ABI = [
  'function approve(address spender,uint256 amount) returns (bool)',
  'function allowance(address owner,address spender) view returns (uint256)',
  'function balanceOf(address owner) view returns (uint256)',
  'function decimals() view returns (uint8)',
];

const SWAP_ABI = [
  'function protocolFee() view returns (uint256)',
  'function protocolFeeWallet() view returns (address)',
  'function requiredSenderKind() view returns (bytes4)',
  'function nonceUsed(address signer,uint256 nonce) view returns (bool)',
  'function swap(address recipient,uint256 maxRoyalty,(uint256 nonce,uint256 expiry,(address wallet,address token,bytes4 kind,uint256 id,uint256 amount) signer,(address wallet,address token,bytes4 kind,uint256 id,uint256 amount) sender,address affiliateWallet,uint256 affiliateAmount,uint8 v,bytes32 r,bytes32 s) order) external',
];

const ORDER_TYPES = {
  Order: [
    { name: 'nonce', type: 'uint256' },
    { name: 'expiry', type: 'uint256' },
    { name: 'protocolFee', type: 'uint256' },
    { name: 'signer', type: 'Party' },
    { name: 'sender', type: 'Party' },
    { name: 'affiliateWallet', type: 'address' },
    { name: 'affiliateAmount', type: 'uint256' },
  ],
  Party: [
    { name: 'wallet', type: 'address' },
    { name: 'token', type: 'address' },
    { name: 'kind', type: 'bytes4' },
    { name: 'id', type: 'uint256' },
    { name: 'amount', type: 'uint256' },
  ],
};

async function main() {
  const provider = new ethers.providers.JsonRpcProvider(RPC);
  const sender = new ethers.Wallet(SENDER_PRIVATE_KEY, provider);
  const signer = new ethers.Wallet(SIGNER_PRIVATE_KEY, provider);

  const swap = new ethers.Contract(SWAP, SWAP_ABI, provider);
  const protocolFee = await swap.protocolFee();
  const requiredSenderKind = await swap.requiredSenderKind();
  const protocolFeeWallet = await swap.protocolFeeWallet();

  const weth = new ethers.Contract(WETH, ERC20_ABI, provider);
  const usdc = new ethers.Contract(USDC, ERC20_ABI, provider);

  const [wethDec, usdcDec] = await Promise.all([weth.decimals(), usdc.decimals()]);

  const senderAmount = ethers.utils.parseUnits(process.env.SENDER_WETH || '0.001', wethDec);
  const signerAmount = ethers.utils.parseUnits(process.env.SIGNER_USDC || '0.994', usdcDec);

  const feeAmount = senderAmount.mul(protocolFee).div(10000);
  const senderTotal = senderAmount.add(feeAmount);

  const before = {
    sender: {
      address: sender.address,
      eth: ethers.utils.formatEther(await provider.getBalance(sender.address)),
      weth: ethers.utils.formatUnits(await weth.balanceOf(sender.address), wethDec),
      usdc: ethers.utils.formatUnits(await usdc.balanceOf(sender.address), usdcDec),
    },
    signer: {
      address: signer.address,
      eth: ethers.utils.formatEther(await provider.getBalance(signer.address)),
      weth: ethers.utils.formatUnits(await weth.balanceOf(signer.address), wethDec),
      usdc: ethers.utils.formatUnits(await usdc.balanceOf(signer.address), usdcDec),
    },
  };

  const wethSender = weth.connect(sender);
  const usdcSigner = usdc.connect(signer);

  const allowanceWeth = await weth.allowance(sender.address, SWAP);
  if (allowanceWeth.lt(senderTotal)) {
    const tx = await wethSender.approve(SWAP, senderTotal);
    console.log('approveWETH', tx.hash);
    await tx.wait();
  }

  const allowanceUsdc = await usdc.allowance(signer.address, SWAP);
  if (allowanceUsdc.lt(signerAmount)) {
    const tx = await usdcSigner.approve(SWAP, signerAmount);
    console.log('approveUSDC', tx.hash);
    await tx.wait();
  }

  const nonce = Number(process.env.NONCE || Math.floor(Date.now() / 1000));
  const used = await swap.nonceUsed(signer.address, nonce);
  if (used) throw new Error('Nonce already used. Set NONCE to a fresh value.');
  const expiry = Number(process.env.EXPIRY || (nonce + 3600));

  const kindErc20 = requiredSenderKind;

  const orderToSign = {
    nonce,
    expiry,
    protocolFee: protocolFee.toNumber(),
    signer: {
      wallet: signer.address,
      token: USDC,
      kind: kindErc20,
      id: 0,
      amount: signerAmount.toString(),
    },
    sender: {
      wallet: sender.address,
      token: WETH,
      kind: kindErc20,
      id: 0,
      amount: senderAmount.toString(),
    },
    affiliateWallet: ethers.constants.AddressZero,
    affiliateAmount: 0,
  };

  const domain = {
    name: 'SWAP',
    version: '4.2',
    chainId: 8453,
    verifyingContract: SWAP,
  };

  const sig = await signer._signTypedData(domain, ORDER_TYPES, orderToSign);
  const split = ethers.utils.splitSignature(sig);

  const orderForCall = {
    nonce,
    expiry,
    signer: {
      wallet: signer.address,
      token: USDC,
      kind: kindErc20,
      id: 0,
      amount: signerAmount,
    },
    sender: {
      wallet: sender.address,
      token: WETH,
      kind: kindErc20,
      id: 0,
      amount: senderAmount,
    },
    affiliateWallet: ethers.constants.AddressZero,
    affiliateAmount: 0,
    v: split.v,
    r: split.r,
    s: split.s,
  };

  const swapSender = swap.connect(sender);
  const tx = await swapSender.swap(sender.address, 0, orderForCall);
  console.log('swapTx', tx.hash);
  const receipt = await tx.wait();
  console.log('swapStatus', receipt.status, 'gasUsed', receipt.gasUsed.toString());

  const after = {
    sender: {
      address: sender.address,
      eth: ethers.utils.formatEther(await provider.getBalance(sender.address)),
      weth: ethers.utils.formatUnits(await weth.balanceOf(sender.address), wethDec),
      usdc: ethers.utils.formatUnits(await usdc.balanceOf(sender.address), usdcDec),
    },
    signer: {
      address: signer.address,
      eth: ethers.utils.formatEther(await provider.getBalance(signer.address)),
      weth: ethers.utils.formatUnits(await weth.balanceOf(signer.address), wethDec),
      usdc: ethers.utils.formatUnits(await usdc.balanceOf(signer.address), usdcDec),
    },
    protocolFeeWallet: {
      address: protocolFeeWallet,
      weth: ethers.utils.formatUnits(await weth.balanceOf(protocolFeeWallet), wethDec),
    },
  };

  console.log(JSON.stringify({
    swap: SWAP,
    protocolFee: protocolFee.toString(),
    senderAmount: ethers.utils.formatUnits(senderAmount, wethDec),
    signerAmount: ethers.utils.formatUnits(signerAmount, usdcDec),
    feeAmount: ethers.utils.formatUnits(feeAmount, wethDec),
    before,
    after,
  }, null, 2));
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
